    for(f,list)in&edits{let p=r.join("source").join(f);let original=fs::read_to_string(&p).unwrap();let mut next=original.clone();for(a,b)in list{if a.is_empty(){next.push_str(b);}else{assert_eq!(next.matches(a).count(),1);next=next.replacen(a,b,1);}}let mut back=next.clone();for(a,b)in list.iter().rev(){assert_eq!(back.matches(b).count(),1);back=back.replacen(b,a,1);}assert_eq!(back,original);fs::write(p,next).unwrap();}
    fs::copy(r.join("observer.rs"),r.join("source/crates/zopro-core/src/euler_factor_census.rs")).unwrap();save(r.join("inverse-edits.json"),&json!(edits));save(r.join("build-pins.json"),&json!(source_pins()));
