    let environment=read("/home/ubuntu/src/zopro-perf-work/center-census/run-plan.json")["environment"].clone();let mut steps=vec![];for i in 0..3{steps.push(json!({"kind":"command","name":format!("observe-{i}"),"argv":["taskset","-c","0-31",r.join("native/observer-sdk").to_str().unwrap(),IMAGE,&fixture,r.join(format!("proofs/{i}")).to_str().unwrap()],"timeout_seconds":180}));}
    for i in 0..3{steps.push(json!({"kind":"command","name":format!("verify-{i}"),"argv":[V,IMAGE,IH,r.join(format!("proofs/{i}/0.proof")).to_str().unwrap(),r.join(format!("proofs/{i}/0.public")).to_str().unwrap(),PH],"timeout_seconds":120}));}
